// DE FORMULIERRIJ IN DE BEWERKSTAND — de bewerkkant van het domeinformulier.
//
// Gedragsbron: het blok "Domeinformulieren bewerkbaar" in de bevroren
// `viewer-bevroren/assets/doc.js` (fase C taak 9, r.8919-9077: `formEditSoort`,
// `voldoetAanPatroon`, `patroonPoort`, `formRowVeld`, `formStrook`, `formRij`),
// met `zetLiteral` (r.1775) en `leegSpec` (r.3193). De redenen staan daar
// voluit; hieronder staat per plek wat de vertaling naar Solid ANDERS maakt.
//
// LAZY. Dit bestand hoort in de BEWERKCHUNK en niet in de leeschunk (spec §1).
// Twee dingen houden dat vast: `formulier.tsx` haalt deze module met `lazy()`
// binnen, en de mutatiekern komt hieronder met een DYNAMISCHE import mee —
// `stores/lazy-grens.test.ts` bewaakt precies die tweede regel.
//
// GEEN NIEUW MUTATIEPAD. Het ✎ opent het veld dat deze module al bouwde, en het
// ✕ loopt langs dezelfde save als dat veld. Alles gaat door `voerUit`, dus door
// het mutatielog: elke bewerking hier is met één `ongedaan()` terug te draaien.
import { Show, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { setIri, termOptions, zetLiteral } from '../../model/edit.js';
import {
  geldigeIriTekst, termVan as termVanJs, voldoetAanPatroon,
} from '../../model/velden.js';
import type { Graaf, Quad, Term } from '../../model-grens.js';
import { graaf, graafVersie } from '../../stores/corpus.js';
import {
  bewerkbron, bronRijen, maakBewerkbaar,
} from '../../stores/bronbeheer.js';
import type { BronBewerk } from '../../stores/bronbeheer.js';
import { huidigeTaal, tekst, zetMelding } from '../../stores/weergave.js';
import { ActieStrook, actieStand, ontgrendelUitleg } from '../bewerk/strook.jsx';
import type { IcoonStand } from '../bewerk/strook.jsx';
import { InlineVeld, IriCombobox, optieTekst } from '../bewerk/veld.jsx';
import type { IriOptie, VeldHaak } from '../bewerk/veld.jsx';
import { LangeTekst } from '../gedeeld/langetekst.jsx';
import { FormulierWaarden } from './formulier.jsx';
import type { FormRij } from './formulier-model.js';
import './formulier.css';

// DE MUTATIEKERN, dynamisch. Een gewone `import … from` op de mutatiekern ziet
// er onschuldig uit en zou de hele bewerklaag de leeschunk in trekken zodra iets
// in het leespad dit bestand ooit statisch aanraakt. De dynamische vorm is de
// eis van spec §1 en wordt door `stores/lazy-grens.test.ts` bewaakt — die leest
// de BRON regel voor regel, dus ook een toelichting die het pad NOEMT telt daar
// mee; vandaar dat het hier omschreven staat en niet uitgeschreven.
const kern = await import('../../stores/bewerk.js');
const { voerUit, bewerkbaar } = kern;

// De modellaag is JavaScript; hier staat de termdecoder één keer getypeerd in
// plaats van met een cast per aanroep (dezelfde afspraak als model-grens.ts).
// Hier stond een eigen `nn`-cast, gedragsidentiek aan die in
// `ui/bewerk/kaartveld.tsx` (eindreview I-2); de decoder zelf woont nu in
// `model/term.js` en wordt via de veldlaag doorgegeven.
const alsTerm = termVanJs as (x: unknown) => Term | null;

interface KaleStore { getQuads(s: Term|null, p: Term|null, o: Term|null, g: Term|null): Quad[] }
type Facade = Record<string, unknown>;

const opties = termOptions as unknown as (g: Graaf) => Record<string, IriOptie[]>;
const schrijfIri = setIri as unknown as
  (f: Facade, term: string, pred: string, iri: string) => void;
/** De meertalige tekst-save uit de modellaag: hij vervangt chirurgisch de
 *  literal die de weergave TOONT en laat de vertaling ernaast staan. `lees` is
 *  de kale graaf; de facade routeert schrijfacties naar de bewerkbron en is dus
 *  niet de plek om de bestaande literalvorm uit te lezen. */
const schrijfTekst = zetLiteral as unknown as (
  f: Facade, lees: unknown, term: string, pred: string, waarde: string,
  standaard?: { lang?: string; datatype?: string },
) => void;

// --- sh:pattern -------------------------------------------------------------

/** DE REGEL ZELF KOMT UIT DE MODELLAAG (review I-5). Hij stond hier met een
 *  eigen body, en tegelijk in `model/velden.js` met dezelfde drie regels
 *  (anchor-vrij, leeg altijd goed, kapot patroon geen oordeel) en bijna
 *  dezelfde toelichting — twee lanes hadden hem onafhankelijk uit doc.js
 *  r.8940-8970 gebouwd. Eén SHACL-regel hoort één keer te bestaan, en dan in de
 *  modellaag: DOM-vrij en in node getoetst (`model/test/velden.test.mjs`).
 *
 *  De re-export blijft staan omdat `formulier-bewerk.test.tsx` hem als
 *  ingang gebruikt en omdat deze module de FORMULIER-kant van de regel is: wat
 *  hier woont, is de POORT eronder — die kent de rij, het label en de melding,
 *  en dat is UI. */
export { voldoetAanPatroon };

/** De patroonpoort van ÉÉN rij, gedeeld door de tekst- en de IRI-tak. SHACL zet
 *  geen enkele beperking op de waardevorm waarop sh:pattern mag staan: hij
 *  toetst de string-vorm, en die bestaat ook voor een IRI ("^https://" komt in
 *  het wild voor). Zou alleen de tekst-tak toetsen, dan slaat een
 *  URIViewer-rij met een patroon stilzwijgend op wat de shape verbiedt.
 *
 *  WAAROP getoetst wordt: op de waarde die anders zou worden WEGGESCHREVEN — in
 *  de tekst-tak de ruwe invoer, in de IRI-tak de opgeloste IRI. Dezelfde waarde
 *  staat daarom ook in de melding. */
export function patroonPoort(rij: FormRij, waarde: string): boolean {
  if (voldoetAanPatroon(waarde, rij.pattern)) return true;
  zetMelding('edit.ongeldigPatroon', { invoer: waarde, veld: rij.label });
  return false;
}

// --- Welk widget? -----------------------------------------------------------

/** Rechtstreeks uit dash:viewer (LiteralViewer/LangStringViewer -> tekst,
 *  URIViewer/LabelViewer -> IRI); een rij zonder widget-hint valt terug op het
 *  soort van de al gerenderde waarde (forms.js/valueItem koos toen al tussen
 *  'text' en 'link'/'label') — zo is het bewerkveld altijd van hetzelfde soort
 *  als wat de kijkstand toonde. */
export function veldSoort(rij: FormRij): 'literal' | 'iri' | null {
  if (rij.viewer === 'LiteralViewer' || rij.viewer === 'LangStringViewer') return 'literal';
  if (rij.viewer === 'URIViewer' || rij.viewer === 'HyperlinkViewer' || rij.viewer === 'LabelViewer') return 'iri';
  const v0 = rij.values[0];
  if (!v0) return null;
  return v0.kind === 'text' ? 'literal' : 'iri';
}

// --- De ontgrendel-route ----------------------------------------------------

/** De bron waaruit deze knoop komt terwijl zij NIET de bewerkbron is — de bron
 *  die de lezer kan omzetten om deze rij alsnog te kunnen bewerken. Sinds het
 *  één-bewerkbron-besluit (spec-addendum 6 sep) is dat één ondubbelzinnige
 *  vraag; de bevroren viewer moest hier nog over meerdere schrijfbronnen heen
 *  kijken (`ontgrendelbareBron`). */
function ontgrendelbareBron(term: string | null): BronBewerk | null {
  const g = graaf() as unknown as KaleStore | null;
  if (!g || !term) return null;
  const graphs = new Set(g.getQuads(alsTerm(term), null, null, null)
    .map((q) => (q.graph as { value?: string } | undefined)?.value)
    .filter((v): v is string => !!v));
  if (!graphs.size) return null;
  const huidig = bewerkbron();
  return bronRijen().find((b) => graphs.has(b.graph) && b.graph !== (huidig ? huidig.graph : null))
    || null;
}

// --- De rij -----------------------------------------------------------------

/** Eén formulierrij als "waarde + strook".
 *
 *  De strook hangt in DEZELFDE regel als de waarde (niet eronder), zodat de rij
 *  in de kijk- en de bewerkstand even hoog is — de enige toegestane
 *  layoutsprong is de strook zelf.
 *
 *  DRIE RIJEN BLIJVEN KIJKSTAND, en om drie verschillende redenen:
 *   - een INVERSE rij ([ sh:inversePath p ]): haar waarde hangt aan
 *     (waarde, p, deze knoop). Op `path` schrijven zou de getoonde waarde laten
 *     staan en er een verzonnen triple in de tegenovergestelde richting naast
 *     zetten. Omkeren is een echte bewerking op een ANDERE knoop;
 *   - een MEERWAARDIGE rij: `InlineVeld` en `IriCombobox` zijn enkelwaardige
 *     widgets, en `setIri`/`zetLiteral` zouden de andere waarden meenemen.
 *     (Vertalingen van één waarde tellen niet mee: forms.js heeft die al tot één
 *     rij-waarde teruggebracht, en `zetLiteral` vervangt chirurgisch.);
 *   - een rij zonder pad of zonder herkenbaar soort: er valt niets aan te wijzen
 *     om naartoe te schrijven.
 *  Elk van de drie houdt haar reden op het gedimde ✎ — vóór taak 9b toonde zo'n
 *  rij niets en zag de lezer alleen dát er geen ✎ stond. */
export default function FormulierRijBewerk(props: {
  rij: FormRij;
  term: string | null;
  /** De eerlijkheidsnoot staat als alinea in beeld en krijgt een textarea:
   *  Enter is daar een newline, niet "opslaan". */
  meerregelig?: boolean;
}): JSX.Element {
  const rij = () => props.rij;
  const [haak, zetHaak] = createSignal<VeldHaak | null>(null);
  const [leeg, zetLeeg] = createSignal<(() => void) | null>(null);

  // Waarom deze rij (nog) niet te bewerken is — de drie kijkstand-redenen, in
  // de volgorde van de bevroren viewer.
  const nvt = (): string | null => {
    if (rij().inverse) return tekst('edit.veldOmgekeerd');
    if (rij().values.length > 1) return tekst('edit.veldMeerwaardig');
    if (!rij().path) return tekst('edit.veldGeenPad');
    return null;
  };
  const soort = () => veldSoort(rij());
  const mag = () => !nvt() && !!props.term && !!soort() && bewerkbaar(props.term);
  const huidig = () => rij().values[0] || null;

  const kaleWaarde = () => (props.meerregelig
    ? <LangeTekst tekst={rij().values.map((v) => v.text).join(', ')} />
    : <FormulierWaarden rij={rij()} />);

  // --- De tekst-tak ---------------------------------------------------------
  const oudeTekst = () => (huidig() ? huidig()!.text : '');
  const bewaarTekst = (nieuw: string): void => {
    // Niets veranderd = niets doen. Een blur op een veld dat de lezer alleen
    // maar heeft aangeklikt zou anders een volledige herbouw én een undo-stap
    // opleveren.
    if (String(nieuw) === oudeTekst()) return;
    void voerUit((f: unknown) => schrijfTekst(
      f as Facade, graaf(), props.term as string, rij().path as string, nieuw,
      // De taal van de BESTAANDE waarde wint; `standaard` geldt alleen als het
      // veld leeg was — wat op een domeinformulier niet voorkomt (forms.js laat
      // lege rijen weg), maar het klopt dan wel.
      { lang: huidigeTaal() },
    ), { groep: true });
  };

  // --- De IRI-tak -----------------------------------------------------------
  const iriOpties = (): IriOptie[] => {
    void graafVersie();
    const g = graaf() as Graaf | null;
    return g ? (opties(g).labeled || []) : [];
  };
  let vorige = '';
  const kiesIri = (iri: string): void => {
    // Een LEEG veld is een geldige bewerking (de eigenschap weghalen); alles wat
    // er wél staat moet een bruikbare IRI opleveren. Zo niet: melden en het veld
    // laten staan zoals de gebruiker het typte — niets gemuteerd.
    if (iri && !geldigeIriTekst(iri)) {
      zetMelding('edit.ongeldigeIri', { invoer: iri });
      return;
    }
    // ONGEWIJZIGD komt er altijd doorheen, en dus vóór de patroonpoort: een
    // waarde die er al stond mag geen klacht opleveren omdat de gebruiker het
    // veld even aanraakte. Weigeren laat `vorige` staan.
    if (iri === vorige) return;
    if (!patroonPoort(rij(), iri)) return;
    vorige = iri;
    void voerUit(
      (f: unknown) => schrijfIri(f as Facade, props.term as string, rij().path as string, iri),
      { groep: true },
    );
  };

  // --- Het ✕: leegmaken IS verwijderen (taak 9c) ----------------------------
  // Het loopt langs precies dezelfde save als het veld zelf — leeg = weghalen
  // (`zetLiteral`/`setIri` ruimen het predicaat op). Geen tweede schrijfpad dus,
  // alleen een tweede knop ervoor. De patroontoets slaat het bewust over: een
  // sh:pattern zegt iets over de VORM van een waarde die er staat, niets over
  // haar afwezigheid.
  const maakLeeg = (): void => {
    // HOEVEEL TRIPLES RAAKT DIT? Meer dan één betekent dat er meer verdwijnt dan
    // de lezer op het scherm ziet (de @en naast de @nl van een meertalige noot).
    // Dat is precies de grens waarop de rest van deze laag om bevestiging vraagt.
    const g = graaf() as unknown as KaleStore | null;
    const n = g && props.term && rij().path
      ? g.getQuads(alsTerm(props.term), alsTerm(rij().path as string), null, null).length : 0;
    if (n > 1 && !window.confirm(tekst('edit.veldLeegVraag'))) return;
    if (soort() === 'iri') {
      void voerUit(
        (f: unknown) => schrijfIri(f as Facade, props.term as string, rij().path as string, ''),
        { groep: true },
      );
      return;
    }
    void voerUit((f: unknown) => schrijfTekst(
      f as Facade, graaf(), props.term as string, rij().path as string, '',
    ), { groep: true });
  };

  // --- De strook ------------------------------------------------------------
  // DE ROUTE BESTAAT ALLEEN ALS DE BRON HET PROBLEEM IS. Twee remmen, elk met
  // zijn eigen reden: bij een inverse of meerwaardige rij ligt het niet aan de
  // bron (`nvt`), en bij een knoop die al ín de bewerkbron leeft valt er niets
  // te ontgrendelen — dan is een leeg veld gewoon leeg, en hoort het ✕ uit te
  // staan met díe reden in plaats van met een slotje.
  const route = () => (nvt() || !props.term || bewerkbaar(props.term)
    ? null : ontgrendelbareBron(props.term));
  // ÉÉN KLIK, MET DE UITLEG ERVOOR (eigenaarsbesluit 9 sep 2026: "make editable
  // doesn't need a confirmation button"). Hier stond de ontgrendel-DOOS van deze
  // rij: een mini-dialoog met "Maak dit de bewerkbron" / "Annuleren". De ja/nee-
  // stap is vervallen — een lokale kopie is omkeerbaar en laat het originele
  // bestand ongemoeid — en de zinnen die erin stonden zijn naar de tooltip van
  // hetzelfde icoon verhuisd (`ontgrendelUitleg` in `ui/bewerk/strook.tsx`). Wat
  // er ná de klik gebeurt meldt de bronnenlaag op de statusregel.
  const opOntgrendel = () => {
    const b = route();
    if (b) void maakBewerkbaar(b).catch(() => {});
  };
  const uitleg = () => {
    const b = route();
    return b ? ontgrendelUitleg({
      naam: b.name || b.url || '',
      huidige: bewerkbron()?.name,
      waarschuw: !b.opfs,
    }) : undefined;
  };

  const bewerkStand = (): IcoonStand => actieStand({
    mag: mag(),
    titel: tekst('edit.veldBewerken'),
    actie: () => haak()?.openBewerk(),
    // Ontgrendelen helpt alleen als de rij zelf wél bewerkbaar ZOU zijn: bij een
    // inverse of meerwaardige rij is de bron niet het probleem.
    ontgrendelbaar: !!route(),
    opOntgrendel,
    ontgrendelUitleg: uitleg(),
    nvt: nvt() || undefined,
  });

  const wisStand = (): IcoonStand => actieStand({
    mag: mag() && !!leeg(),
    titel: tekst('edit.veldLeegmaken'),
    actie: () => leeg()?.(),
    ontgrendelbaar: !!route(),
    opOntgrendel,
    ontgrendelUitleg: uitleg(),
    // Een LEEG veld heeft niets weg te halen; dat is een andere reden dan de
    // drie kijkstand-redenen en hij hoort er dus achteraan.
    nvt: nvt() || tekst('edit.veldAlLeeg'),
  });

  return (
    <span class="form-rij">
      <Show when={mag()} fallback={kaleWaarde()}>
        <Show
          when={soort() === 'iri'}
          fallback={(
            <InlineVeld
              waarde={oudeTekst()}
              meerregelig={props.meerregelig}
              // De rij draagt haar ✎ in de actiestrook rechts, en die opent dit
              // veld via de haak — geen tweede potlood vlak achter de waarde.
              zonderPotlood
              // De waarde die er AL staat komt er altijd doorheen, ook als zij
              // zelf niet aan het patroon voldoet: het ✎ opendoen en weer
              // wegklikken mag geen klacht opleveren over data die de gebruiker
              // niet heeft aangeraakt (en die hij hier misschien juist kwam
              // repareren).
              valideer={(v) => String(v) === oudeTekst() || patroonPoort(rij(), v)}
              onSave={bewaarTekst}
              haak={(api) => { zetHaak(() => api); zetLeeg(() => (oudeTekst() ? maakLeeg : null)); }}
            />
          )}
        >
          <IriCombobox
            options={iriOpties()}
            value={optieTekst(iriOpties(), huidig() ? huidig()!.iri : null)}
            onPick={kiesIri}
            haak={(api) => {
              vorige = huidig()?.iri || '';
              zetHaak(() => api);
              zetLeeg(() => (huidig()?.iri ? maakLeeg : null));
            }}
          />
        </Show>
      </Show>
      {/* GEEN ⋯: een veld kent geen structuuracties. Het is de enige plek waar de
          strook uit drie iconen bestaat in plaats van vier — bewust, want een
          leeg menu op elke rij van elk formulier is ruis, geen uitleg. */}
      <ActieStrook
        sleep={{ aan: false, titel: tekst('edit.veldSleepNvt') }}
        bewerk={bewerkStand()}
        verwijder={wisStand()}
      />
    </span>
  );
}
